arguments.command:
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
out=$(bash bin/render event)
echo "$out" | grep -q 'action=' || { echo "render"; fail=1; }
# Every query key must be valid on the Cirrus function URL: A-Z a-z 0-9 _ . -
for u in $(echo "$out" | grep -o 'action="[^"]*"' | sed 's/action="//;s/"$//'); do
  k=${u#\?}; k=${k%%=*}
  [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "invalid query key: $k"; fail=1; }
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/orders/5012/refund?action=refund' | grep -q '^200 refund' || { echo "handle refund"; fail=1; }
bash bin/handle POST '/events/1/edit?action=nope' | grep -q '^404' || { echo "unknown action"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo "exit $?"

